  rights: [R('rm-d014', 'Licensed vendors were told to clear a notified vending zone by noon, with no hearing. Is that lawful?', [
    ['a', 'No. Livelihood and due process require a lawful order, a hearing, and the procedure for notified vending zones.', true, 'Correct. The right to livelihood is protected by fair procedure; a one-line notice is not one.'],
    ['b', 'Yes. The municipality owns the pavement and can clear it at will.', false, 'Public ownership does not remove the duty of fair procedure toward licensed vendors.'],
    ['c', 'Yes, if a hearing is held afterwards.', false, 'A hearing after the carts are crushed cannot restore what was taken.'],
  ], 'Article 21 protects livelihood through fair procedure; street vending in notified zones is governed by law requiring committee decisions and hearings before eviction.', 'The notice had no order number and no committee; stopping it cost nothing and prevented an unlawful clearance.', SRC.liberty, {
    question: 'Licensed sellers were told to leave a legal selling zone by noon, with no hearing. Is that allowed?',
    options: ['No. They need a lawful order and a hearing first.', 'Yes. The city owns the pavement.', 'Yes, if a hearing happens afterwards.'],
    feedback: ['Yes! People’s livelihoods need fair steps first.', 'No. Owning the pavement does not cancel fair process.', 'A hearing after the carts are crushed is too late.'],
    principle: 'People’s livelihoods are protected. Nobody can be evicted without a lawful order and a hearing.',
    why: 'The notice had no order and no committee. Stopping it cost nothing.',
  })],
